 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    from collections import Counter
    counts = Counter(v for row in g for v in row if v not in (2, 8))
    bg = counts.most_common(1)[0][0] if counts else 1
    divider_row = next((r for r in range(h) if all(v == 2 for v in g[r])), None)
    divider_col = next((c for c in range(w) if all(g[r][c] == 2 for r in range(h))), None)
    object_cells = [(r, c, g[r][c]) for r in range(h) for c in range(w)
                    if g[r][c] not in (bg, 2, 8)]
    if not object_cells:
        return g
    if divider_row is not None:
        top = min(r for r, c, v in object_cells)
        bottom = max(r for r, c, v in object_cells)
        if bottom < divider_row:
            shift = divider_row - 1 - bottom
            stripe = top + shift - 1
        else:
            shift = divider_row + 1 - top
            stripe = bottom + shift + 1
        original = list(object_cells)
        for r, c, v in original:
            g[r][c] = bg
        for r, c, v in original:
            g[r + shift][c] = v
        if 0 <= stripe < h and stripe != divider_row:
            g[stripe] = [8] * w
    elif divider_col is not None:
        left = min(c for r, c, v in object_cells)
        right = max(c for r, c, v in object_cells)
        shift = divider_col - 1 - right if right < divider_col else divider_col + 1 - left
        original = list(object_cells)
        for r, c, v in original:
            g[r][c] = bg
        for r, c, v in original:
            g[r][c + shift] = v
        stripe = left + shift - 1 if right < divider_col else right + shift + 1
        if 0 <= stripe < w:
            for r in range(h):
                g[r][stripe] = 8
    return g
